-- SafetyTraining v20.062
-- Evidence enrichment for already-draft first-aid update LUs. Keeps existing version ids used by draft course compositions.

with target as (
 select lu.id learning_unit_id,lu.stable_key,luv.id version_id,luv.content
 from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1 and luv.status='draft'
 where lu.stable_key in ('update:firstaid:scene-assessment','update:firstaid:vital-functions','update:firstaid:trauma-bleeding','update:firstaid:medical-exposure','update:firstaid:a-complex-trauma','update:firstaid:a-simulation')
), enriched as (
 select version_id,stable_key,
  content || jsonb_build_object('didactic_version','first-aid-update-v2','quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'scenario_based',true,'practical_focus',true,'skills_refresh',true),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','normative_validation','D.M. 388/2003','reuse_policy','reference_and_original_rewrite'),'evidence_sources',jsonb_build_array(jsonb_build_object('authority','Ministero della Salute - Gazzetta Ufficiale','title','D.M. 15 luglio 2003, n. 388','url','https://www.gazzettaufficiale.it/atto/vediMenuHTML?atto.codiceRedazionale=004G0046&atto.dataPubblicazioneGazzetta=2004-02-03&tipoSerie=serie_generale&tipoVigenza=originario','use','normative_validation','checked_on','2026-10-15'),jsonb_build_object('authority','INAIL','title','Il primo soccorso nei luoghi di lavoro','url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html','use','technical_reference','checked_on','2026-10-15')) || case when stable_key='update:firstaid:vital-functions' then jsonb_build_array(jsonb_build_object('authority','INAIL','title','La diffusione e l’utilizzo dei defibrillatori (DAE) nei luoghi di lavoro','url','https://www.inail.it/content/dam/inail-hub-site/documenti/catalogo-generale/2025/06/Diffusione%20e%20utilizzo%20Defibrillatori.pdf','use','technical_reference_citation_only','checked_on','2026-10-15')) when stable_key='update:firstaid:medical-exposure' then jsonb_build_array(jsonb_build_object('authority','INAIL','title','Rischio chimico sui luoghi di lavoro - primo soccorso in caso di infortunio','url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2025.01.rischio-chimico-sui-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html','use','chemical_first_aid_reference','checked_on','2026-10-15')) else '[]'::jsonb end,'delivery_note','L’aggiornamento deve rinnovare capacità operative effettive. Il materiale digitale prepara e supporta il debrief, ma non sostituisce le esercitazioni pratiche previste dal D.M. 388/2003.')
  || case stable_key
   when 'update:firstaid:scene-assessment' then jsonb_build_object('refresh_drill',jsonb_build_object('title','60 secondi: scena, aiuto, chiamata','scenario_rotation',jsonb_build_array('macchina/energia non isolata','traffico interno','sospetta esposizione chimica','persona a terra in area apparentemente sicura'),'task','A ogni scenario il corsista deve dire entro 60 secondi: entro/non entro, quale pericolo controllo, chi attivo, quali informazioni do al 112/118 e chi prepara l’accesso dei soccorsi.','observer_checklist',jsonb_build_array('riconosce pericolo prima del contatto','non ritarda la chiamata','descrive fatti e non diagnosi','comunica luogo/accesso','assegna un compito utile a un secondo addetto')),'call_handover_refresh',jsonb_build_array('luogo e accesso','evento','numero coinvolti','condizioni osservate','pericoli residui','azioni già effettuate','recapito e persona che attende i soccorsi'))
   when 'update:firstaid:vital-functions' then jsonb_build_object('skills_refresh_station',jsonb_build_object('title','Riconoscimento + RCP/DAE: prova osservata e feedback','stations',jsonb_build_array('sicurezza e riconoscimento','attivazione soccorsi e richiesta DAE','sequenza RCP su manichino secondo protocollo insegnato','uso trainer DAE','sicurezza durante analisi/scarica','continuità fino al cambio scenario'),'evaluation','Il docente osserva abilità pratiche, corregge subito errori critici e fa ripetere il passaggio fino a esecuzione coerente con il protocollo adottato.','copyright_note','Il riferimento INAIL 2025 sul DAE è citato soltanto come fonte tecnica; nessuna grafica o testo viene riprodotto.'),'critical_errors',jsonb_build_array('ritardo ingiustificato nell’allarme','mancata sicurezza della scena','contatto con la persona durante analisi/scarica DAE','interruzioni non necessarie','uso di manovre non apprese'))
   when 'update:firstaid:trauma-bleeding' then jsonb_build_object('trauma_refresh_station',jsonb_build_object('title','Emorragia + trauma: decisione e tecnica appresa','scenario','Ferita sanguinante dopo caduta con possibile trauma associato: il corsista usa DPI, attiva aiuto, applica la tecnica di controllo del sanguinamento insegnata, evita movimenti/manovre improprie e prepara il passaggio di consegne.','observer_checklist',jsonb_build_array('protezione da fluidi','allertamento adeguato','tecnica pratica coerente con addestramento','nessuna rimozione di corpi conficcati','nessun riallineamento improvvisato','monitoraggio e handover')),'handover_fields',jsonb_build_array('dinamica','ora','sanguinamento/segni osservati','cambiamenti','azioni e presidi utilizzati','altre criticità traumatiche'))
   when 'update:firstaid:medical-exposure' then jsonb_build_object('medical_exposure_refresh',jsonb_build_object('title','Malore o esposizione: riconosci la priorità e trova l’informazione giusta','cases',jsonb_build_array('dolore toracico/difficoltà respiratoria','segni neurologici improvvisi','convulsione/perdita di coscienza','schizzo chimico o inalazione sospetta','ustione termica'),'task','Per ogni caso: protezione della scena, segni da descrivere, quando chiamare, cosa monitorare, quale procedura/SDS recuperare, cosa NON improvvisare.','chemical_rule','Per esposizioni chimiche usare SDS/etichetta/procedura e indicazioni sanitarie specifiche; non provocare vomito né usare neutralizzanti o rimedi generici di iniziativa.'),'anti_diagnosis_rule','L’aggiornamento verifica capacità di riconoscere e riferire; non la capacità di formulare diagnosi mediche.')
   when 'update:firstaid:a-complex-trauma' then jsonb_build_object('group_a_complex_drill',jsonb_build_object('title','Più coinvolti e pericolo residuo: organizzazione della squadra','scenario','Due persone coinvolte in area industriale, una non responsiva e una traumatizzata, con fonte di rischio che richiede messa in sicurezza tecnica.','roles',jsonb_build_array('coordinatore addetti','chiamata 112/118','messa in sicurezza/attivazione tecnico competente','assistenza alla priorità critica','preparazione presidi/DAE','guida dei soccorsi'),'task','Il gruppo deve assegnare i ruoli, dichiarare cosa non farà finché la scena non è sicura, mantenere aggiornato il 112/118 e organizzare il passaggio ai professionisti.'),'debrief_questions',jsonb_build_array('Quale decisione ha evitato un secondo infortunato?','Quale informazione mancava?','Quale ruolo era ambiguo?','Che cosa va cambiato nel piano aziendale?'))
   when 'update:firstaid:a-simulation' then jsonb_build_object('integrated_simulation_rubric',jsonb_build_object('title','Scenario aziendale completo con rubric di valutazione','criteria',jsonb_build_array('sicurezza scena','riconoscimento priorità','allertamento e qualità informazioni','assegnazione compiti','abilità pratiche pertinenti','uso corretto dei presidi disponibili','comunicazione continua','accesso soccorsi e handover','stop davanti a manovra non appresa','debrief e azione correttiva'),'rating',jsonb_build_array('da correggere','adeguato con supporto','autonomo e coerente con addestramento'),'rule','Ogni partecipante deve ricoprire almeno un ruolo operativo e ricevere un feedback specifico; gli errori critici vanno riprovati in condizioni didattiche sicure.'),'organizational_debrief',jsonb_build_array('presidi disponibili e accessibili?','numeri e procedure chiari?','chi apre accessi/guida soccorsi?','rischi specifici coperti dagli scenari?','azioni di miglioramento con responsabile/scadenza?'))
   end as new_content
 from target
)
update public.learning_unit_versions luv set content=e.new_content,content_hash=md5(e.new_content::text),status='draft',published_at=null from enriched e where luv.id=e.version_id;

insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'gu-dm388-2003','normative_validation','Fonte normativa primaria per aggiornamento della formazione degli addetti al primo soccorso.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key like 'update:firstaid:%'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-primo-soccorso-2018','technical_reference','Riferimento tecnico-didattico per scenari e organizzazione delle capacità di primo soccorso.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key like 'update:firstaid:%'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-dae-2025','technical_reference_citation_only','Riferimento INAIL 2025 per refresh RCP/DAE; sola citazione, nessuna riproduzione.',date '2026-10-15',jsonb_build_object('reuse_policy','citation_only_reference') from public.learning_units lu where lu.stable_key='update:firstaid:vital-functions'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-primo-soccorso-chimico-2025','chemical_first_aid_reference','Riferimento INAIL 2025 per aggiornamento su esposizioni chimiche e consultazione SDS.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='update:firstaid:medical-exposure'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
